<!DOCTYPE html>
<html lang="zh-CN">
<head>
  <meta charset="UTF-8">
  <title>灵雾交融场景</title>
  <style>
    html, body {
      margin: 0;
      padding: 0;
      width: 100%;
      min-height: 100vh;
      font-family: 'Microsoft YaHei', monospace;
      overflow-x: hidden;
    }

    body {
      position: relative;
    }

    .background-layer {
      position: fixed;
      top: 0;
      left: 0;
      width: 100%;
      height: 100vh;
      z-index: -1;
      overflow: hidden;
      pointer-events: none;
    }

    /* 蒸汽背景 */
    .background-layer::before,
    .background-layer::after {
      content: "";
      position: absolute;
      width: 200%;
      height: 200%;
      background: radial-gradient(circle, rgba(255,255,255,0.08) 0%, transparent 70%);
      animation: steam 8s infinite linear;
    }
    .background-layer::after {
      animation-delay: 4s;
    }
    @keyframes steam {
      0% {
        transform: translate(-50%, 100%) scale(1.2);
        opacity: 0.4;
      }
      50% {
        opacity: 0.15;
      }
      100% {
        transform: translate(0, -150%) scale(1.6);
        opacity: 0;
      }
    }

    /* 灵气上升 */
    .aura-line {
      position: absolute;
      bottom: -20px;
      width: 2px;
      height: 80px;
      background: rgba(173,216,230, 0.3);
      filter: blur(2px);
      animation: aura-rise 4s linear infinite;
      border-radius: 50px;
    }
    @keyframes aura-rise {
      0% {
        transform: translateY(0) scaleX(1);
        opacity: 0.4;
      }
      100% {
        transform: translateY(-120%) scaleX(1.5);
        opacity: 0;
      }
    }

    .aura-line:nth-child(1) { left: 10%; animation-delay: 0s; }
    .aura-line:nth-child(2) { left: 25%; animation-delay: 1s; }
    .aura-line:nth-child(3) { left: 40%; animation-delay: 2s; }
    .aura-line:nth-child(4) { left: 60%; animation-delay: 0.5s; }
    .aura-line:nth-child(5) { left: 80%; animation-delay: 1.5s; }

    /* 瀑布下落 */
    .water-line {
      position: absolute;
      top: -80px;
      width: 2px;
      height: 100px;
      background: linear-gradient(to bottom, rgba(173,216,230,0.3), transparent);
      animation: water-fall 2s linear infinite;
    }
    @keyframes water-fall {
      0% {
        transform: translateY(0);
        opacity: 0.3;
      }
      100% {
        transform: translateY(120vh);
        opacity: 0;
      }
    }

    .water-line:nth-child(6)  { left: 5%; animation-delay: 0s; }
    .water-line:nth-child(7)  { left: 20%; animation-delay: 1s; }
    .water-line:nth-child(8)  { left: 45%; animation-delay: 2s; }
    .water-line:nth-child(9)  { left: 70%; animation-delay: 3s; }
    .water-line:nth-child(10) { left: 90%; animation-delay: 1.5s; }

    .content {
      padding: 10px;
      max-width: 900px;
      margin: 0 auto;
    }

    .text-content {
      font-size: 16px;
      text-align: left;
    }
  </style>
</head>
<body>

<!-- 背景动画层 -->
<div class="background-layer">
  <!-- 灵气上升 -->
  <div class="aura-line"></div>
  <div class="aura-line"></div>
